/** Deductions of the latest regular payroll run by type, largest first, with each type's share of the total. */
function deductionBreakdown(){
 const run=latestPayrollRun(read<PayrollRun[]>(RUNS_KEY,[]));
 if(!run)return null;
 const sum=(pick:(row:PayrollRun['rows'][number])=>number)=>run.rows.reduce((total,row)=>total+(Number(pick(row))||0),0);
 const parts:Array<[string,number]>=[['SSS',sum(row=>row.result.sss)],['PhilHealth',sum(row=>row.result.phil)],['Pag-IBIG',sum(row=>row.result.pagibig)],['Withholding Tax',sum(row=>row.result.tax)],['Loans',sum(row=>row.result.loans)],['Absences, Late & Undertime',sum(row=>row.result.absences+row.result.late+row.result.undertime)]];
 const total=sum(row=>row.result.deductions);
 parts.push(['HMO & Other',Math.max(0,total-parts.reduce((known,[,amount])=>known+amount,0))]);
 return {label:runLabel(run),total,items:parts.filter(([,amount])=>amount>0.004).map(([label,amount])=>({label,amount,percent:total>0?amount/total*100:0})).sort((a,b)=>b.amount-a.amount)};
}
